let budget = 1000;     // starting interrupt budget
const CALL_COST = 1;   // entering the function
const EDGE_COST = 1;   // one backward jump (loop iteration)
const ITERS = 300;     // loop iterations per call

let totalBackEdges = 0;
let tierUpCall = 0;
let tierUpEdge = 0;

for (let call = 1; call <= 4 && tierUpCall === 0; call++) {
  budget -= CALL_COST;
  for (let i = 0; i < ITERS; i++) {
    budget -= EDGE_COST;
    totalBackEdges++;
    if (budget <= 0 && tierUpCall === 0) {
      tierUpCall = call;
      tierUpEdge = totalBackEdges;
    }
  }
}

console.log('tierUpEdge=' + tierUpEdge + ' tierUpCall=' + tierUpCall);

tasks.starter:
// values is mostly numbers, but uses the string 'END' as a terminator sentinel
function sumUntilEnd(values) {
  let total = 0;
  for (let i = 0; i < values.length; i++) {
    if (values[i] === 'END') break;   // string compared against number elements
    total += values[i];               // Add slot sees Smi... then a string shows up
  }
  return total;
}

model.en:
Keep the hot loop's data monomorphic: store only numbers in the array and signal the end with a separate length/index or a numeric sentinel, so the <code>Add</code> feedback slot only ever sees Smis and TurboFan's integer-add speculation never breaks:<br><code>// Carry the real length separately; array holds numbers only.
function sumUntilEnd(values, count) {
  let total = 0;
  for (let i = 0; i &lt; count; i++) {
    total += values[i]; // always a number -> stable feedback, no deopt
  }
  return total;
}</code><br>Mixing a string sentinel into a numeric hot path pollutes the feedback vector: the loop's <code>Add</code> and comparison slots see two types, so optimised code that assumed Smis hits the string, fails its speculation, and deopts back to the interpreter (the dispatch loop) — every pass. Removing the off-type value lets the budget tier the function up and keeps it on the fast tier. Alternatives: use a typed array (numbers only by construction) or a separate boolean/length channel for the terminator.

model.ru:
Держите данные горячего цикла мономорфными: храните в массиве только числа и сигнализируйте конец отдельной длиной/индексом или числовым сентинелом, чтобы слот обратной связи <code>Add</code> видел только Smi, и целочисленная спекуляция TurboFan не ломалась:<br><code>// Несём настоящую длину отдельно; массив хранит только числа.
function sumUntilEnd(values, count) {
  let total = 0;
  for (let i = 0; i &lt; count; i++) {
    total += values[i]; // всегда число -> стабильная обратная связь, без деопта
  }
  return total;
}</code><br>Подмешивание строкового сентинела в числовой горячий путь загрязняет feedback vector: слоты <code>Add</code> и сравнения цикла видят два типа, поэтому оптимизированный код, предположивший Smi, натыкается на строку, проваливает спекуляцию и деоптимизируется обратно в интерпретатор (цикл диспетчеризации) — на каждом проходе. Удаление значения чужого типа позволяет бюджету повысить ярус функции и держать её на быстром ярусе. Альтернативы: использовать типизированный массив (по построению только числа) или отдельный булев/длинный канал для терминатора.
